() => {
  const f = document.getElementById('flyer');
  const r = f.getBoundingClientRect();
  const out = {flyer:[r.width,r.height], scrollH:f.scrollHeight, fontLoaded: document.fonts.check('800 74px Inter')};
  out.sections = [...f.children].map(c=>({cls:c.className, h:Math.round(c.getBoundingClientRect().height), top:Math.round(c.getBoundingClientRect().top)}));
  // overflow check for any element beyond flyer bounds
  const bad=[];
  f.querySelectorAll('*').forEach(e=>{const b=e.getBoundingClientRect();
    if(b.width&&(b.left<r.left-0.5||b.right>r.right+0.5||b.top<r.top-0.5||b.bottom>r.bottom+0.5)) bad.push([e.className||e.tagName, Math.round(b.left),Math.round(b.top),Math.round(b.right),Math.round(b.bottom)]);
    if(e.scrollWidth>e.clientWidth+1&&e.children.length===0) bad.push(['clipX:'+(e.className||e.tagName), e.scrollWidth, e.clientWidth]);
  });
  out.bad=bad;
  return out;
}

