  const out={sections:[...f.children].map(c=>({cls:c.className,h:Math.round(c.getBoundingClientRect().height),top:Math.round(c.getBoundingClientRect().top)}))};
  const nms=[...f.querySelectorAll('.cand')].map(c=>{const n=c.querySelector('.nm').getBoundingClientRect();return [Math.round(n.left),Math.round(n.right),Math.round(n.width)];});
  out.names=nms;
  out.gaps=[nms[1][0]-nms[0][1], nms[2][0]-nms[1][1]];
  const bad=[];
  f.querySelectorAll('*').forEach(e=>{const b=e.getBoundingClientRect();
    if(b.width&&(b.left<r.left-0.5||b.right>r.right+0.5||b.top<r.top-0.5||b.bottom>r.bottom+0.5)) bad.push([e.className||e.tagName,Math.round(b.left),Math.round(b.right)]);
    if(e.children.length===0&&e.scrollWidth>e.clientWidth+1) bad.push(['clipX:'+(e.className||e.tagName),e.scrollWidth,e.clientWidth]);});
  out.bad=bad;
  const fo=f.querySelector('footer').getBoundingClientRect();
  out.footer={w:Math.round(fo.width), sw:f.querySelector('footer').scrollWidth, cw:f.querySelector('footer').clientWidth};
  return out;
}

